CREATE GENERATOR GEN_USUARIOS_ID; CREATE GENERATOR GEN_LIBROS_ID; CREATE GENERATOR GEN_LECTORES_ID; CREATE GENERATOR GEN_PRESTAMOS_ID; CREATE GENERATOR GEN_ORDENES_ID; CREATE GENERATOR GEN_NOTIFICACIONES_ID; CREATE GENERATOR GEN_AUDITORIA_ID;
SET TERM ^ ;
CREATE OR ALTER TRIGGER TR_USUARIOS_BI FOR USUARIOS ACTIVE BEFORE INSERT POSITION 0 AS BEGIN IF (NEW.ID IS NULL) THEN NEW.ID=GEN_ID(GEN_USUARIOS_ID,1); END^
CREATE OR ALTER TRIGGER TR_LIBROS_BI FOR LIBROS ACTIVE BEFORE INSERT POSITION 0 AS BEGIN IF (NEW.ID IS NULL) THEN NEW.ID=GEN_ID(GEN_LIBROS_ID,1); END^
