CREATE OR ALTER TRIGGER TR_PRESTAMOS_BI FOR PRESTAMOS ACTIVE BEFORE INSERT POSITION 0 AS BEGIN IF (NEW.ID IS NULL) THEN NEW.ID=GEN_ID(GEN_PRESTAMOS_ID,1); END^
CREATE OR ALTER TRIGGER TR_ORDENES_BI FOR ORDENES_RECLAMO ACTIVE BEFORE INSERT POSITION 0 AS BEGIN IF (NEW.ID IS NULL) THEN NEW.ID=GEN_ID(GEN_ORDENES_ID,1); END^
CREATE OR ALTER TRIGGER TR_NOTIFICACIONES_BI FOR NOTIFICACIONES ACTIVE BEFORE INSERT POSITION 0 AS BEGIN IF (NEW.ID IS NULL) THEN NEW.ID=GEN_ID(GEN_NOTIFICACIONES_ID,1); END^
CREATE OR ALTER TRIGGER TR_AUDITORIA_BI FOR AUDITORIA ACTIVE BEFORE INSERT POSITION 0 AS BEGIN IF (NEW.ID IS NULL) THEN NEW.ID=GEN_ID(GEN_AUDITORIA_ID,1); END^
SET TERM ; ^
